package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Explicit independent private-journal import. No read or merge resumes after process death. */
public final class DiaryImportActivity extends Activity implements DiaryImportJob.Observer {
 private DiaryImportJob job;private final Set<String> asNew=new HashSet<>();private boolean conflicts;private int page;private String reviewed="",local="";private Dialog detail;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();job=retained instanceof DiaryImportJob?(DiaryImportJob)retained:new DiaryImportJob(getApplicationContext(),saved!=null);if(saved!=null){conflicts=saved.getBoolean("conflicts");page=saved.getInt("page");reviewed=saved.getString("reviewed","");ArrayList<String> selected=saved.getStringArrayList("asNew");if(selected!=null)asNew.addAll(selected);}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);job.observe(this);}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 public void changed(DiaryImportJob.State state){if(isDestroyed())return;DiaryImport.Review review=state.review;if(review!=null){String key=review.source+"/"+review.fingerprint;if(!reviewed.equals(key)){reviewed=key;asNew.clear();page=0;conflicts=false;}}else if(state.phase==DiaryImportJob.Phase.READING){asNew.clear();reviewed="";conflicts=false;page=0;}LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,conflicts&&review!=null?"Review diary conflicts":"Import private diary",this::back);Design.space(body,12);if(conflicts&&review!=null){renderConflicts(body,review,state.busy());return;}Design.text(body,"Separate diary JSON only",18,600,Design.INK);Design.space(body,8);Design.text(body,"This document contains private dreams, reflections and dates. It is not a sleep-record backup. Import only a copy you choose; nothing is uploaded or read automatically.",13,400,Design.MUTED);Design.space(body,12);if(review!=null){Design.item(body,"memory","Entries in document",Integer.toString(review.total),null);Design.item(body,"plus","New IDs",Integer.toString(review.fresh.size()),null);Design.item(body,"check","Identical IDs · skip",Integer.toString(review.identical),null);Design.item(body,"info","Conflicting IDs",Integer.toString(review.conflicts.size()),null);Design.text(body,"Immutable document SHA-256: "+review.source,10,400,Design.MUTED);if(!review.conflicts.isEmpty()){Design.space(body,12);Design.text(body,asNew.size()+" conflicts import as new · "+(review.conflicts.size()-asNew.size())+" keep current",14,600,Design.BROWN);Design.button(body,"Review conflicts",false,()->{conflicts=true;page=0;changed(job.state());}).setEnabled(!state.busy());Design.button(body,"Keep all current conflicts",false,()->{asNew.clear();changed(job.state());}).setEnabled(!state.busy());Design.button(body,"Import all conflicts as new",false,()->{asNew.clear();for(DiaryImport.Conflict item:review.conflicts)asNew.add(item.incoming.id);changed(job.state());}).setEnabled(!state.busy());}Design.space(body,12);Design.text(body,"Merge adds "+(review.fresh.size()+asNew.size())+" entries. Identical entries are skipped. Existing entries are never overwritten or deleted. Imported historical entries have no alarm-challenge ownership; original text, dates and origin labels are kept.",13,400,Design.MUTED);if(review.total==0)Design.text(body,"This document has no entries to merge.",14,500,Design.BROWN);}else Design.text(body,"Up to 4 MiB and 2,000 entries. The document is validated before any merge. Existing diaries up to 10,000 entries and a bounded 64 MiB review scan are supported.",12,400,Design.MUTED);Design.space(body,12);if(!state.message.isEmpty())Design.text(body,state.message,13,500,Design.BROWN);if(!local.isEmpty())Design.text(body,local,13,500,Design.BROWN);LinearLayout footer=RecordUi.footer(body);if(state.phase==DiaryImportJob.Phase.REVIEW&&review!=null)Design.button(footer,"Merge reviewed diary",true,()->{local="";job.merge(asNew);}).setEnabled(review.total>0);if(!state.busy())Design.button(footer,review==null?"Choose diary JSON":"Choose another diary JSON",state.phase!=DiaryImportJob.Phase.REVIEW,this::choose);if(state.phase==DiaryImportJob.Phase.READING||state.phase==DiaryImportJob.Phase.MERGING)Design.button(footer,"Cancel import",false,this::cancel);else if(state.phase!=DiaryImportJob.Phase.CHOOSING)Design.button(footer,state.phase==DiaryImportJob.Phase.DONE?"Open diary":"Close",false,()->{if(state.phase==DiaryImportJob.Phase.DONE)startActivity(RecordUi.intent(this,DiaryActivity.class));finish();});}
 private void renderConflicts(LinearLayout body,DiaryImport.Review review,boolean busy){int pages=Math.max(1,(review.conflicts.size()+19)/20);page=Math.max(0,Math.min(page,pages-1));Design.text(body,"Same ID, different saved content",16,600,Design.INK);Design.text(body,"Keep current changes nothing. Import as new preserves the current entry and adds the incoming entry under a fresh UUID, with no challenge owner.",13,400,Design.MUTED);for(int n=page*20;n<Math.min(review.conflicts.size(),(page+1)*20);n++){DiaryImport.Conflict item=review.conflicts.get(n);Design.space(body,16);Design.text(body,"Current: "+title(item.current),14,600,Design.INK);Design.text(body,"Incoming: "+title(item.incoming),14,500,Design.MUTED);Design.text(body,"Updated "+RecordUi.date(item.current.updated,java.time.ZoneId.systemDefault())+" / "+RecordUi.date(item.incoming.updated,java.time.ZoneId.systemDefault()),11,400,Design.MUTED);LinearLayout choices=RecordUi.segments(body,new String[]{"Keep current","Import as new"},asNew.contains(item.incoming.id)?1:0,choice->{if(choice==1)asNew.add(item.incoming.id);else asNew.remove(item.incoming.id);changed(job.state());});RecordUi.enabled(choices,!busy);Design.button(body,"Read both entries",false,()->{if(detail!=null)detail.dismiss();detail=SleepPicker.message(this,"Conflicting diary entries","CURRENT\n"+item.current.title+"\n"+item.current.text+"\n\nINCOMING\n"+item.incoming.title+"\n"+item.incoming.text);});Design.line(body);}Design.space(body,10);Design.text(body,"Conflict page "+(page+1)+" of "+pages,12,400,Design.MUTED);if(page>0)Design.button(body,"Previous conflicts",false,()->{page--;changed(job.state());});if(page+1<pages)Design.button(body,"Next conflicts",false,()->{page++;changed(job.state());});Design.button(RecordUi.footer(body),"Return to merge review",true,()->{conflicts=false;changed(job.state());});}
 private static String title(DiaryStore.Entry entry){return entry.title.isBlank()?"Untitled entry":entry.title;}
 private void choose(){if(!job.choose())return;local="";try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json"),job.request);}catch(RuntimeException unavailable){job.cancelChoice();local="Android Files could not be opened.";changed(job.state());}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=job.request)return;if(result!=RESULT_OK||data==null||data.getData()==null)job.cancelChoice();else job.read(data.getData());}
 private void cancel(){boolean accepted=job.cancel();local=accepted?"Cancellation requested; waiting for the current operation to close.":"The merge has reached its commit boundary. Wait for its final result.";changed(job.state());}
 private void back(){if(job.state().busy()){cancel();return;}if(conflicts){conflicts=false;changed(job.state());}else finish();}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
 @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("conflicts",conflicts);out.putInt("page",page);out.putString("reviewed",reviewed);out.putStringArrayList("asNew",new ArrayList<>(asNew));}
 @Override protected void onDestroy(){if(detail!=null)detail.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
